// home.component.scss - نسخه قبلی
:host {
  // پالت رنگ استاندارد لابراتوار دندانسازی
  --white-clean: #ffffff;
  --white-off: #f8f9fa;
  --gray-light: #e9ecef;
  --gray-medium: #6c757d;
  --gray-dark: #343a40;
  --navy-blue: #1a237e;      // آبی نفتی پزشکی
  --medical-blue: #1565c0;   // آبی پزشکی
  --teal-modern: #00695c;    // سبز فیروزه‌ای
  --ice-blue: #4fc3f7;       // آبی یخی
  --black-luxury: #212121;   // مشکی لوکس
  --charcoal: #424242;       // طوسی پررنگ
  
  // استفاده در کامپوننت‌ها
  --primary: var(--navy-blue);
  --secondary: var(--teal-modern);
  --accent: var(--ice-blue);
  --background: var(--white-clean);
  --text-dark: var(--black-luxury);
  --text-muted: var(--gray-medium);
  --border-color: var(--gray-light);
}
.home-page {
  overflow-x: hidden;
  font-family: 'Vazir', 'Segoe UI', Tahoma, Geneva, Verdana, sans-serif;
  line-height: 1.6;
  color: var(--dark-text);
  font-size: 14px;
  margin: 0;
  padding: 0;
  background: var(--background);
  width: 100%;
  max-width: 100%;
}

.container {
  max-width: 100%;
  margin: 0 auto;
  padding: 0 16px;
  
  @media (max-width: 1200px) {
    max-width: 100%;
  }
  
  @media (max-width: 768px) {
    max-width: 100%;
    padding: 0 12px;
  }
}

.top-bar {
  background: var(--gray-900);
  color: white;
  padding: 10px 0;
  font-size: 12px;
  border-bottom: none;
  width: 100%;
  
  .container {
    max-width: 100%;
  }
  
  .top-bar-content {
    display: flex;
    justify-content: space-between;
    align-items: center;
    height: 36px;
    
    @media (max-width: 768px) {
      flex-direction: column;
      height: auto;
      gap: 8px;
    }
  }
  
  .contact-info {
    display: flex;
    gap: 24px;
    align-items: center;
    
    .phone {
      font-weight: 500;
      font-size: 13px;
    }
    
    .delivery-time {
      color: var(--gray-300);
      font-size: 11px;
    }
    
