/* ===== RESET & BASE STYLES ===== */
* {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
}

:root {
  /* Color System - Modern Dental Clinic Colors */
  --primary-blue: #1a73e8;
  --primary-dark: #1565c0;
  --medical-teal: #00bcd4;
  --medical-light: #80deea;
  --accent-gold: #ffb300;
  --accent-coral: #ff6b6b;
  
  /* Neutral Colors */
  --dark-charcoal: #2c3e50;
  --gray-dark: #34495e;
  --gray-medium: #7f8c8d;
  --gray-light: #bdc3c7;
  --gray-lighter: #ecf0f1;
  --pure-white: #ffffff;
  
  /* Gradients */
  --gradient-primary: linear-gradient(135deg, var(--primary-blue), var(--medical-teal));
  --gradient-dark: linear-gradient(135deg, var(--dark-charcoal), var(--gray-dark));
  --gradient-accent: linear-gradient(135deg, var(--accent-gold), var(--accent-coral));
  
  /* Shadows */
  --shadow-sm: 0 2px 10px rgba(0, 0, 0, 0.08);
  --shadow-md: 0 8px 30px rgba(0, 0, 0, 0.12);
  --shadow-lg: 0 20px 60px rgba(0, 0, 0, 0.15);
  --shadow-xl: 0 25px 50px rgba(0, 0, 0, 0.2);
  
  /* Border Radius */
  --radius-sm: 8px;
  --radius-md: 12px;
  --radius-lg: 16px;
  --radius-xl: 24px;
  --radius-full: 50px;
  
  /* Spacing */
  --space-xs: 0.5rem;
  --space-sm: 1rem;
  --space-md: 1.5rem;
  --space-lg: 2rem;
  --space-xl: 3rem;
  --space-2xl: 4rem;
  
  /* Typography */
  --font-primary: 'Inter', 'Segoe UI', Tahoma, Geneva, Verdana, sans-serif;
  --font-heading: 'Poppins', var(--font-primary);
}

html {
  scroll-behavior: smooth;
  font-size: 16px;
}

body {
  font-family: var(--font-primary);
  line-height: 1.7;
  color: var(--dark-charcoal);
  background: var(--pure-white);
  overflow-x: hidden;
}

